import { describe, expect, it } from 'vitest'
import {
  corridorSpreads,
  quoteIllustration,
  windowRangeBps,
} from './modulePresentation'
import type { ModulesConfig, ModulesView } from './modules'
import cases from './moduleSpreadParity.json'

// Generated by tests/module_spread_parity.rs from the bot's own
// base_spreads → evaluate → apply path. Each case is the bps the RFQ book
// prices with in Live; the Simulate table must show exactly that.
type Case = {
  config: ModulesConfig
  spreads: ModulesView['corridor_spreads']
  price: number
  share: number
  window: { low: number; high: number; extra_bps: number } | null
  quoted: [number | null, number | null]
}

describe('the Simulate table quotes what the bot quotes', () => {
  it.each((cases as Case[]).map((c, i) => [i, c] as const))(
    'case %i',
    (_, c) => {
      const base = corridorSpreads(c.spreads, c.price)
      expect(base).not.toBeNull()
      const [buy, sell] = c.quoted
      expect(
        quoteIllustration(
          c.config,
          base!,
          c.share,
          c.window && windowRangeBps(c.window)
        ).quoted
      ).toEqual({ buy, sell })
    }
  )
})
